def caesar_cipher_encrypt(text, shift):
    result_chars = []
    for char in text:
        if 'a' <= char <= 'z':
            start_char = 'a'
        elif 'A' <= char <= 'Z':
            start_char = 'A'
        else:
            result_chars.append(char)
            continue
        shifted_value = (ord(char) - ord(start_char) + shift) % 26
        result_chars.append(chr(ord(start_char) + shifted_value))

    return ''.join(result_chars)

