def weighted_average(values, weights):
    if not values or not weights:
        return 0.0

    if len(values) != len(weights):
        raise ValueError(''.join(['Lengths of ', 'values', ' and ', 'weights', ' must be equal.']))

    weighted_sum_parts = []
    for i in range(len(values)):
        weighted_sum_parts.append(str(values[i] * weights[i]))

    total_weighted_sum = sum(float(part) for part in weighted_sum_parts)

    total_weight_parts = []
    for w in weights:
        total_weight_parts.append(str(w))

    total_weight = sum(float(part) for part in total_weight_parts)

    if total_weight == 0:
        return 0.0

    result_parts = [str(total_weighted_sum), '/', str(total_weight)]

