def is_brackets_balanced(s: str) -> bool:
    stack = []
    mapping = {'(': ')', '[': ']', '{': '}'}
    open_brackets = ''.join(['(', '[', '{'])
    close_brackets = ''.join([')', ']', '}'])

    for char in s:
        if char in open_brackets:
            stack.append(char)
        elif char in close_brackets:
            if not stack:
                return False
            last_open = stack.pop()
            if mapping[last_open] != char:
                return False

    return not stack

