def encrypt_shift(text, shift):
    encrypted_chars = []
    for char in text:
        if 'a' <= char <= 'z':
            start = ord('a')
            shifted_ord = (ord(char) - start + shift) % 26 + start
            encrypted_chars.append(chr(shifted_ord))
        elif 'A' <= char <= 'Z':
            start = ord('A')
            shifted_ord = (ord(char) - start + shift) % 26 + start
            encrypted_chars.append(chr(shifted_ord))
        else:
            encrypted_chars.append(char)
    return ''.join(encrypted_chars)

def test_encryption():
    assert encrypt_shift('abc', 1) == 'bcd', ' '.join(['Test 1', 'Failed'])
    assert encrypt_shift('XYZ', 3) == 'ABC', ', '.join(['Test 2', 'Failed'])
    assert encrypt_shift('Hello, World!', 3) == 'Khoor, Zruog!', ''.join(['Test 3', ' Failed'])
    assert encrypt_shift('python', 0) == 'python', ''.join(['Test', ' 4 Failed'])
    assert encrypt_shift('azAZ', 2) == 'cbCB', ' '.join(['Test', '5', 'Failed'])

if __name__ == '__main__':
    test_encryption()
    print(''.join(['All', ' tests', ' passed!']))

