def convert_length(value: float, from_unit: str, to_unit: str) -> float:
    meter_to_feet_factor = 3.28084

    valid_units = ['m', 'ft']
    if from_unit not in valid_units or to_unit not in valid_units:
        error_msg_parts = ["Invalid unit provided. ", "Allowed units: ", ', '.join(valid_units), "."]
        raise ValueError(''.join(error_msg_parts))

    if from_unit == to_unit:
        return value

    if ''.join([from_unit, to_unit]) == 'mft':
        return value * meter_to_feet_factor
    elif ''.join([from_unit, to_unit]) == 'ftm':
        return value / meter_to_feet_factor

    raise ValueError(''.join(["Unexpected unit combination: ", from_unit, " to ", to_unit, "."]))

